import {tex} from './math.mjs';
import {cantwell1Lessons,cantwell2Lessons} from './cantwell-content.mjs';
import {dihedral,vertexMap,rotate,slope,odeSolution,heat,nonlinear,nonlinearResidual,nullspace,dimensions,dimensionalResidual,rescale,dragNumbers,stokes,keplerPi,period,mach,capillary,dropTime,rowing} from './cantwell-math.mjs';
const fmt=x=>Number.isFinite(x)?x.toLocaleString('es',{maximumSignificantDigits:5}):'no definido';
const eq=s=>tex(s,true),para=s=>`<p>${s}</p>`,result=s=>`<div class="result-box" aria-live="polite">${s}</div>`;
const range=(id,label,min,max,step,value)=>`<div class="field"><label for="cw-${id}">${label} <output id="cw-${id}-value">${fmt(value)}</output></label><input class="range" type="range" id="cw-${id}" min="${min}" max="${max}" step="${step}" value="${value}"></div>`;
const select=(id,label,opts)=>`<div class="field"><label for="cw-${id}">${label}</label><select id="cw-${id}">${opts.map(([v,t])=>`<option value="${v}">${t}</option>`).join('')}</select></div>`;
const colors=['#6ce2bc','#ffac95','#b9a7ff','#ffd27d','#8fcef9','#f29ecd'];
const svg=(body,label)=>`<svg viewBox="0 0 520 330" role="img" aria-label="${label}" class="cw-svg">${body}</svg>`;
function plot(series,{xmin=0,xmax=6,ymin=0,ymax=1.1,xlabel='x',ylabel='y',label='Gráfico calculado'}={}){
 const X=x=>55+(x-xmin)/(xmax-xmin)*440,Y=y=>280-(y-ymin)/(ymax-ymin)*245;
 const paths=series.map((s,k)=>{let d='',pen=false;for(let j=0;j<=220;j++){const x=xmin+(xmax-xmin)*j/220,y=s.fn(x);if(y===null||!Number.isFinite(y)||y<ymin||y>ymax){pen=false;continue;}d+=(pen?'L':'M')+X(x).toFixed(2)+','+Y(y).toFixed(2);pen=true;}return `<path d="${d}" fill="none" stroke="${colors[k%colors.length]}" stroke-width="2.5"/><text x="60" y="${17+k*16}" fill="${colors[k%colors.length]}" font-size="11">${s.name}</text>`;}).join('');
 return svg(`<path d="M55 35V280H495" fill="none" stroke="#8592b3"/>${[0,.25,.5,.75,1].map(t=>`<path d="M55 ${Y(ymin+t*(ymax-ymin))}H495" stroke="#53607c" opacity=".25"/><text x="48" y="${Y(ymin+t*(ymax-ymin))+4}" text-anchor="end" fill="#c4cee3" font-size="11">${fmt(ymin+t*(ymax-ymin))}</text>`).join('')}${paths}<text x="270" y="318" text-anchor="middle" fill="#d4def0">${xlabel} · ${fmt(xmin)} a ${fmt(xmax)}</text><text x="60" y="298" fill="#d4def0">${ylabel}</text>`,label);
}
export function renderCantwell(chapter,section,container){
 const lesson=(chapter===1?cantwell1Lessons:cantwell2Lessons)[section-1],type=lesson.lab;
 const setup={
  broken:()=>range('delta','Perturbación δ',0,.35,.01,.15)+range('angle','Giro α (grados)',0,360,10,120),
  hexagon:()=>select('a','Operación A',Array.from({length:12},(_,j)=>[j,j<6?`r^${j} · giro`:`r^${j-6}s · reflexión`]))+select('b','Operación B',Array.from({length:12},(_,j)=>[j,j<6?`r^${j} · giro`:`r^${j-6}s · reflexión`])),
  units:()=>range('mass','log factor de masa',-2,2,.1,.5)+range('length','log factor de longitud',-2,2,.1,.7)+range('time','log factor de tiempo',-2,2,.1,-.3),
  continuous:()=>select('flow','Flujo',[['rotation','Rotación'],['dilation','Dilatación positiva']])+range('parameter','Parámetro s',-2,2,.05,.7),
  slope:()=>range('shear','Cizalla a',-2,2,.1,1)+range('slope','Pendiente p',-2,2,.1,-.5),
  ode:()=>range('constant','Constante C',-2,3,.1,1)+range('shift','Traslación s',-1.5,1.5,.1,.5),
  heat:()=>range('t','Tiempo t',.2,3,.1,1)+range('k','Difusividad κ',.2,2,.1,1),
  nonlinear:()=>range('s','Parámetro s',-1,2,.05,1)+range('t','Tiempo t',0,2,.1,.5),
  weights:()=>select('equation','Ecuación',[['ns','Navier–Stokes'],['stokes','Stokes no estacionario'],['euler','Euler']])+range('a','Peso espacial a',-2,2,.1,1)+range('b','Peso temporal b',-4,4,.1,2)+range('c','Peso de velocidad c',-3,3,.1,-1)+range('d','Peso de presión d',-5,5,.1,-2),
  pi:()=>select('system','Variables',[['drag','Arrastre: D, ρ, U, r, μ'],['kepler','Dos cuerpos: G, M, m, a, b, T'],['contact','Contacto: F, E*, R, a']]),
  kepler:()=>range('e','Excentricidad e',0,.9,.01,.5)+range('q','Razón de masas m/M',0,1,.01,.1)+range('a','Semieje mayor a',.5,3,.1,1),
  drag:()=>range('D','Fuerza D (N)',.1,10,.1,1)+range('rho','Densidad ρ (kg/m³)',500,1500,50,1000)+range('U','Velocidad U (m/s)',.1,3,.1,1)+range('r','Radio r (m)',.01,.1,.005,.05)+range('mu','Viscosidad μ (Pa·s)',.01,1,.01,.1),
  stokes:()=>range('mu','Viscosidad μ (Pa·s)',.1,2,.1,1)+range('U','Velocidad U (mm/s)',.1,10,.1,1)+range('r','Radio r (mm)',.1,2,.1,1),
  mach:()=>range('U','Velocidad U (m/s)',50,800,10,350)+range('T','Temperatura T∞ (K)',200,600,10,300)+range('gamma','Razón γ',1.1,1.67,.01,1.4),
  scales:()=>range('scale','Escala de radio λ',.25,4,.05,2)+select('extra','Rugosidad y túnel',[['fixed','Mantener k y L fijos'],['scaled','Escalar también k y L']]),
  capillary:()=>range('d','Diámetro del tubo (mm)',.2,4,.1,1)+range('theta','Ángulo de contacto (grados)',0,160,5,30)+range('r','Radio de gota (mm)',.1,3,.1,1),
  scaling:()=>range('force','Razón de fuerza F/F₀',.2,8,.2,2)+select('model','Hipótesis de área mojada',[['similar','Área ∝ n^(2/3)'],['fixed','Área ∝ n'],['alternate','Área ∝ n^(1/2)']])+range('n','Número de remeros n',1,8,1,4)
 };
 container.innerHTML=`<div class="lab cw-lab"><div class="viz"><div class="viz-header"><span>CANTWELL · LABORATORIO ${chapter}.${section}</span><span class="viz-tag">MODELO CALCULADO</span></div><div id="cw-viz"></div></div><div class="control-panel"><h3>${lesson.nav}</h3><p class="helper">${lesson.desc}</p>${setup[type]()}<div id="cw-result"></div></div></div><div class="insight"><p id="cw-insight"></p></div>`;
 const $=id=>container.querySelector('#cw-'+id),val=id=>Number($(id).value),str=id=>$(id).value;
 function update(){
  container.querySelectorAll('input[type="range"]').forEach(el=>{$(el.id.slice(3)+'-value').textContent=fmt(Number(el.value));});let visual='',out='',insight='';
  if(type==='broken'){
   const delta=val('delta'),ang=val('angle')*Math.PI/180,curve=shift=>Array.from({length:241},(_,j)=>{const t=j*2*Math.PI/240,r=1+delta*Math.cos(3*(t-shift));return `${260+100*r*Math.cos(t)},${165-100*r*Math.sin(t)}`;}).join(' '),err=2*delta*Math.abs(Math.sin(3*ang/2));
   visual=svg(`<polyline points="${curve(0)}" fill="none" stroke="${colors[0]}" stroke-width="3"/><polyline points="${curve(ang)}" fill="none" stroke="${colors[1]}" stroke-width="2" stroke-dasharray="6 4"/>`,'Figura perturbada original y girada');out=result(eq(String.raw`r(\theta)=1+\delta\cos(3\theta)`)+para(`Desajuste radial máximo: ${fmt(err)}. ${err<1e-9?'El giro conserva la figura.':'El giro rompe la simetría de esta figura.'}`));insight='Verde: original. Naranja: girada. Con δ=0 todos los giros encajan; con δ≠0 prueba 0°, 120° y 240°.';
  } else if(type==='hexagon'){
   const unpack=x=>[x%6,x>=6?1:0],a=unpack(val('a')),b=unpack(val('b')),ab=dihedral(a,b),ba=dihedral(b,a),map=vertexMap(...ab),label=op=>`r^{${op[0]}}${op[1]?'s':''}`;
   const pts=Array.from({length:6},(_,j)=>[260+105*Math.cos(j*Math.PI/3),165-105*Math.sin(j*Math.PI/3)]);visual=svg(`<polygon points="${pts.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#a8b2ca"/>${map.map((slot,j)=>`<circle cx="${pts[slot][0]}" cy="${pts[slot][1]}" r="16" fill="${colors[j]}"/><text x="${pts[slot][0]}" y="${pts[slot][1]+5}" text-anchor="middle" fill="#10182b">${j}</text>`).join('')}`,'Vértices etiquetados del hexágono después de AB');out=result(eq(String.raw`${label(a)}\,${label(b)}=${label(ab)}`)+para(`Orden inverso: ${tex(label(ba))}. ${ab.join()===ba.join()?'Estas operaciones conmutan.':'Estas operaciones no conmutan.'}`)+para('Mapa de vértices: '+map.map((v,j)=>`${j}→${v}`).join(' · ')));insight='AB aplica B y después A. Las etiquetas muestran qué operación se ha realizado aunque la figura geométrica siga encajando.';
  } else if(type==='units'){
   const base=[2,1000,1,.01,.5],trans=rescale(base,dimensions.drag.matrix,[val('mass'),val('length'),val('time')]);const before=dragNumbers(base[0],base[1],base[2],base[3],base[4]),after=dragNumbers(...trans);
   visual=`<div class="cw-table-wrap"><table class="cw-table"><caption>Acción dimensional sobre magnitudes positivas</caption><thead><tr><th>Variable</th><th>Inicial</th><th>Transformada</th></tr></thead><tbody>${dimensions.drag.names.map((n,j)=>`<tr><th>${n}</th><td>${fmt(base[j])}</td><td>${fmt(trans[j])}</td></tr>`).join('')}</tbody></table></div>`;out=result(para(`Re: ${fmt(before.re)} → ${fmt(after.re)}`)+para(`C_D: ${fmt(before.cd)} → ${fmt(after.cd)}`));insight='Las magnitudes dimensionales cambian; los dos grupos permanecen iguales. Los factores se aplican según los exponentes de M, L y T, no como lectura directa del tamaño de una unidad.';
  } else if(type==='continuous'){
   const s=val('parameter'),rot=str('flow')==='rotation',x=1,y=.5,[X,Y]=rot?rotate(x,y,s):[Math.exp(s)*x,Math.exp(s)*y],scale=35;
   visual=svg(`<path d="M20 165H500M260 15V315" stroke="#7887a9"/><circle cx="260" cy="165" r="${scale*Math.hypot(x,y)}" stroke="#617292" fill="none"/><path d="M260 165L${260+scale*X} ${165-scale*Y}" stroke="${colors[1]}"/><circle cx="${260+scale*x}" cy="${165-scale*y}" r="6" fill="${colors[0]}"/><circle cx="${260+scale*X}" cy="${165-scale*Y}" r="7" fill="${colors[1]}"/>`,'Punto inicial verde y punto transformado naranja con igual escala en ambos ejes');out=result(para(`(x̃,ỹ)=(${fmt(X)}, ${fmt(Y)})`)+para(`x²+y²: ${fmt(x*x+y*y)} → ${fmt(X*X+Y*Y)}`)+para(`y/x: ${fmt(y/x)} → ${fmt(Y/X)}`));insight=rot?'La rotación conserva la distancia al origen. Cerca de x̃=0 la razón ỹ/x̃ deja de ser una coordenada regular.':'La dilatación conserva la razón y/x, pero modifica la norma. El origen permanece fijo; el resto se mueve por semirrectas.';
  } else if(type==='slope'){
   const a=val('shear'),p=val('slope'),P=slope(1,a,0,1,p),dx=1+a*p,dy=p,len=Math.max(1,Math.hypot(dx,dy)),xp=95*dx/len,yp=95*dy/len;
   visual=svg(`<path d="M50 165H470M260 40V290" stroke="#7786a8"/><path d="M260 165l${85/Math.hypot(1,p)} ${-85*p/Math.hypot(1,p)}" stroke="${colors[0]}" stroke-width="4"/><path d="M260 165l${xp} ${-yp}" stroke="${colors[1]}" stroke-width="3"/>`,'Vectores tangentes original y transformado por cizalla');out=result(eq(String.raw`\widetilde p=\frac p{1+ap}`)+para(`Jacobian J=1; 1+ap=${fmt(dx)}.`)+para(P===null?'Tangente vertical: la pendiente respecto a x̃ no está definida.':`Pendiente transformada: ${fmt(P)}`));insight='Verde: tangente inicial. Naranja: imagen. Prueba a=1 y p=−1: el mapa sigue siendo invertible pero la tangente se vuelve vertical.';
  } else if(type==='ode'){
   const C=val('constant'),s=val('shift');visual=plot([{name:'Solución inicial',fn:x=>odeSolution(x,C)},{name:'Solución transformada',fn:x=>odeSolution(x,Math.exp(s)*C)}],{xmin:-2,xmax:3,ymin:-3,ymax:4,label:'Soluciones log(eˣ+C), recortadas donde el argumento no es positivo'});out=result(eq(String.raw`e^y-e^x=C\quad\mapsto\quad e^sC`)+para(`C inicial=${fmt(C)}; C transformada=${fmt(Math.exp(s)*C)}.`)+para(C<0?`Dominio inicial: x>${fmt(Math.log(-C))}.`:'Dominio inicial: todos los x reales.'));insight='La ecuación se conserva aunque cambie la solución concreta. Pon C=0: ambos gráficos coinciden. El corte de la curva respeta el dominio del logaritmo.';
  } else if(type==='heat'){
   const t=val('t'),k=val('k');visual=plot([t/2,t,2*t].map((v,j)=>({name:`t=${fmt(v)}`,fn:x=>heat(x,v,k)})),{xmax:8,label:'Tres perfiles físicos de temperatura normalizada'})+plot([t/2,t,2*t].map((v,j)=>({name:`Mismo perfil en ζ; t=${fmt(v)}`,fn:z=>heat(z*Math.sqrt(k*v),v,k)})),{xlabel:'ζ',ylabel:'u/u₀',label:'Colapso de los tres perfiles en la coordenada de semejanza'});out=result(eq(String.raw`U(\zeta)=\operatorname{erfc}(\zeta/2)`)+para(`Longitud √(κt)=${fmt(Math.sqrt(k*t))}. U(0)=1; U(2)≈${fmt(heat(2,1,1))}.`));insight='Arriba: distintos tiempos en x. Abajo: el mismo perfil en ζ. La aproximación numérica de erfc tiene error absoluto de orden 1,5·10⁻⁷. El modelo es semiinfinito.';
  } else if(type==='nonlinear'){
   const t=val('t'),s=val('s'),w=1+s*t,edge=s<0&&w>0?Math.sqrt(-2*w/s):null;visual=plot([{name:'uₛ(x,t)',fn:x=>nonlinear(x,t,s)}],{xmin:-3,xmax:3,ymin:-6,ymax:6,label:'Solución no lineal en su dominio real'});out=result(eq(String.raw`u_s=-2\log\left(1+s(t+x^2/2)\right)`)+para(`En x=0, w=${fmt(w)}. `+(w<=0?'No hay dominio real a este tiempo para este s.':edge!==null?`Dominio: |x|<${fmt(edge)}.`:'El dominio mostrado es real.'))+para(w>0?`Residuo analítico en x=0: ${fmt(nonlinearResidual(0,t,s))}.`:''));insight='La familia procede de soluciones de calor positivas en w. Los puntos con w≤0 se excluyen. El gráfico recorta además los valores que quedan fuera del rango vertical.';
  } else if(type==='weights'){
   const a=val('a'),b=val('b'),c=val('c'),d=val('d'),kind=str('equation'),terms=[['Tiempo',c-b],['Convección',2*c-a],['Presión',d-a],['Viscosidad',c-2*a]].filter(([n])=>!(kind==='stokes'&&n==='Convección')&&!(kind==='euler'&&n==='Viscosidad')),ok=terms.every(t=>Math.abs(t[1]-terms[0][1])<1e-8);
   visual=`<div class="cw-table-wrap"><table class="cw-table"><caption>Pesos de términos presentes</caption><thead><tr><th>Término</th><th>Peso</th></tr></thead><tbody>${terms.map(([n,v])=>`<tr><th>${n}</th><td>${fmt(v)}</td></tr>`).join('')}</tbody></table></div>`;out=result(para(ok?'Los pesos coinciden: se conserva el conjunto de ceros de la ecuación.':'Los pesos no coinciden: esta dilatación no es una simetría general de la ecuación.')+para(`Incompresibilidad tiene peso ${fmt(c-a)} y mantiene sus ceros.`));insight='Con a=1, prueba b=2,c=−1,d=−2 para Navier–Stokes. En Stokes puedes variar c si ajustas d=c−a. En Euler exige b=a−c y d=2c. Se mantienen ρ y ν fijos.';
  } else if(type==='pi'){
   const sys=dimensions[str('system')],{rank,basis}=nullspace(sys.matrix),matrix=String.raw`\begin{pmatrix}`+sys.matrix.map(r=>r.join('&')).join(String.raw`\\`)+String.raw`\end{pmatrix}`;
   visual=`<div class="cw-table-wrap"><p>Columnas: ${sys.names.join(', ')}. Filas: M, L, T.</p>${eq('A='+matrix)}<table class="cw-table"><caption>Base del núcleo calculada por Gauss</caption><thead><tr><th>Grupo</th>${sys.names.map(n=>`<th>${n}</th>`).join('')}<th>Av</th></tr></thead><tbody>${basis.map((v,j)=>`<tr><th>Π${j+1}</th>${v.map(x=>`<td>${fmt(x)}</td>`).join('')}<td>${dimensionalResidual(sys.matrix,v).map(fmt).join(', ')}</td></tr>`).join('')}</tbody></table></div>`;
   out=result(para(`n=${sys.names.length}, rango=${rank}, n−r=${basis.length}.`)+basis.map((v,j)=>eq(String.raw`\Pi_{${j+1}}=`+v.map((e,k)=>e===0?'':`q_{${k+1}}^{${Number(e.toPrecision(12))}}`).filter(Boolean).join(''))).join(''));insight='Cada fila de exponentes genera un monomio adimensional. En el caso contacto hay tres dimensiones escritas pero rango dos: la fila temporal es dependiente. La base no es única.';
  } else if(type==='kepler'){
   const e=val('e'),q=val('q'),a=val('a'),b=a*Math.sqrt(1-e*e),scale=65,pts=Array.from({length:161},(_,j)=>{const t=2*Math.PI*j/160;return `${260+scale*(a*Math.cos(t)-a*e)},${165-scale*b*Math.sin(t)}`;}).join(' ');
   visual=svg(`<polyline points="${pts}" fill="none" stroke="${colors[0]}" stroke-width="3"/><circle cx="260" cy="165" r="7" fill="${colors[1]}"/><text x="270" y="185" fill="#d4def0">Foco del movimiento relativo</text>`,'Órbita relativa elíptica de dos cuerpos con un foco en el origen');out=result(para(`b=${fmt(b)}, r_A=${fmt(Math.sqrt(a*b))}, T=${fmt(period(a,q))} (GM=1).`)+para(`GMT²/a³=${fmt(4*Math.PI*Math.PI/(1+q))}`)+para(`GMT²/r_A³=${fmt(keplerPi(q,e))}`));insight='La excentricidad cambia el grupo construido con r_A, pero no el periodo si se fijan a y las masas. La dinámica fija 4π²; las dimensiones solo permiten la función.';
  } else if(type==='drag'){
   const D=val('D'),rho=val('rho'),U=val('U'),r=val('r'),mu=val('mu'),{cd,re}=dragNumbers(D,rho,U,r,mu);visual=svg(`<circle cx="260" cy="165" r="${r*900}" fill="#6ce2bc22" stroke="${colors[0]}" stroke-width="3"/><path d="M30 165H140M360 165H480" stroke="${colors[1]}" stroke-width="4"/><text x="35" y="140" fill="#d4def0">U=${fmt(U)} m/s</text><text x="335" y="205" fill="#d4def0">D=${fmt(D)} N</text>`,'Esfera con radio, velocidad incidente y fuerza elegidos');out=result(para(`Re=${fmt(re)}, C_D=${fmt(cd)}`)+para(`D/(μUr)=${fmt(D/(mu*U*r))}; (π/4)C_D Re=${fmt(Math.PI*cd*re/4)}.`));insight='Los controles definen un punto en el espacio de grupos. No todos los pares seleccionados representan una medición física de una esfera: la ley experimental es información adicional.';
  } else if(type==='stokes'){
   const mu=val('mu'),U=val('U')*.001,r=val('r')*.001,rho=1000,D=stokes(mu,U,r),{cd,re}=dragNumbers(D,rho,U,r,mu);visual=plot([{name:'Stokes: Re≤0,1',fn:l=>l<=-1?24/10**l:null},{name:'Extrapolación fuera del régimen',fn:l=>l>=-1?24/10**l:null}],{xmin:-2,xmax:1,ymin:0,ymax:2500,xlabel:'log₁₀ Re',ylabel:'C_D',label:'Ley de Stokes y extrapolación separada fuera de Reynolds pequeño'});out=result(para(`ρ=1000 kg/m³. Re=${fmt(re)}; D=${fmt(D)} N; C_D=${fmt(cd)}.`)+para(`C_D Re=${fmt(cd*re)}.`)+para(re>.1?'Re supera 0,1: usa este resultado como extrapolación, no como predicción precisa.':'Re pequeño: el modelo de Stokes es una aproximación de flujo lento.'));insight='La frontera 0,1 es una referencia didáctica de régimen pequeño, no un cambio brusco de ley física. C_D diverge si Re baja, mientras la fuerza baja con U.';
  } else if(type==='mach'){
   const U=val('U'),T=val('T'),gamma=val('gamma'),R=287,cv=R/(gamma-1),M=mach(U,gamma,R,T);visual=plot([{name:`Mach a U=${fmt(U)} m/s`,fn:v=>mach(U,gamma,R,v)}],{xmin:200,xmax:600,ymin:0,ymax:3,xlabel:'T∞ (K)',ylabel:'Mach',label:'Mach en función de temperatura para velocidad y gas fijados'});out=result(para(`R ilustrativo=287 J/(kg·K), a∞=${fmt(Math.sqrt(gamma*R*T))} m/s.`)+para(`Mach=${fmt(M)}; U²/(cᵥT∞)=${fmt(U*U/(cv*T))}.`)+para(`γ(γ−1)Mach²=${fmt(gamma*(gamma-1)*M*M)}.`));insight='La curva calcula la razón de velocidades en un gas ideal con R fijo. No predice C_D ni la estructura de un choque; Reynolds y otras condiciones deben comprobarse aparte.';
  } else if(type==='scales'){
   const s=val('scale'),scaled=str('extra')==='scaled',r=.01*s,U=1/s,k=.0001*(scaled?s:1),L=.5*(scaled?s:1),re=2*1000*U*r/.1;
   visual=`<div class="cw-table-wrap"><table class="cw-table"><caption>Modelo y prototipo: grupos relevantes</caption><thead><tr><th>Grupo</th><th>Inicial</th><th>Escalado</th></tr></thead><tbody><tr><th>Re</th><td>200</td><td>${fmt(re)}</td></tr><tr><th>k/r</th><td>0,01</td><td>${fmt(k/r)}</td></tr><tr><th>r/L</th><td>0,02</td><td>${fmt(r/L)}</td></tr></tbody></table></div>`;out=result(para(`r=${fmt(r)} m; U=${fmt(U)} m/s.`)+para(scaled?'Se conservan los tres grupos mostrados.':'Re se conserva; rugosidad relativa y confinamiento cambian salvo λ=1.'));insight='Se supone viscosidad y densidad constantes. Conservar los grupos mostrados no cubre escalas que este modelo no ha incluido, como Mach o intensidad turbulenta.';
  } else if(type==='capillary'){
   const d=val('d')*.001,r=val('r')*.001,theta=val('theta')*Math.PI/180,sigma=.072,rho=1000,g=9.81,H=capillary(sigma,rho,g,d,theta),tc=dropTime(rho,r,sigma),uc=Math.sqrt(sigma/(rho*r));visual=plot([{name:'Altura de equilibrio',fn:degrees=>capillary(sigma,rho,g,d,degrees*Math.PI/180)*1000}],{xmin:0,xmax:160,ymin:-160,ymax:160,xlabel:'θ (grados)',ylabel:'H (mm)',label:'Ascenso o descenso capilar frente a ángulo de contacto'});out=result(para(`H=${fmt(H*1000)} mm; t_c=${fmt(tc*1000)} ms; U_c=${fmt(uc)} m/s.`)+para(`Valores ilustrativos: σ=0,072 N/m, ρ=1000 kg/m³, g=9,81 m/s².`));insight='La altura usa el balance de Jurin; la gota usa escalas con prefactor unitario. t_c no es el periodo exacto de oscilación ni U_c un umbral universal de impacto.';
  } else if(type==='scaling'){
   const F=val('force'),model=str('model'),n=val('n');visual=plot([['similar','Área ∝ n^(2/3)'],['fixed','Área ∝ n'],['alternate','Área ∝ n^(1/2)']].map(([m,name])=>({name,fn:x=>rowing(x,m)})),{xmin:1,xmax:8,ymin:.9,ymax:1.5,xlabel:'Número n',ylabel:'U(n)/U(1)',label:'Tres modelos de área mojada para la misma hipótesis de potencia por remero'});out=result(para(`Contacto elástico, R y E* fijos: a/a₀=(F/F₀)^(1/3)=${fmt(Math.cbrt(F))}.`)+para(`Modelo seleccionado: U(${n})/U(1)=${fmt(rowing(n,model))}.`));insight='El exponente de contacto incorpora hipótesis de Hertz. Los tres modelos de remo cambian la ley de área; la comparación ilustra la dependencia de las hipótesis, sin ajustar datos experimentales.';
  }
  $('viz').innerHTML=visual;$('result').innerHTML=out;$('insight').textContent=insight;
 }
 container.querySelectorAll('input,select').forEach(el=>el.addEventListener('input',update));update();
}
